def _traverse_codepoints(self, current_position, n):
    """Traverse from current position by n codepoints (may be negative)"""
    dest = current_position + n
    if n > 0:
        while True:
            if current_position == dest:
                break
            if current_position + READ_CHUNK_SIZE > dest:
                self.read(dest - current_position)
                break
            else:
                ret = self.read(READ_CHUNK_SIZE)
            current_position += READ_CHUNK_SIZE
            if not ret:
                break
    elif n < 0:
        # Seek to start and read up to dest
        self.buffer.seek(0)
        self._tell = 0
        self.read(dest)
    return dest

def seek(self, pos, mode=0):
    """Traverse from offset to the specified codepoint"""
    self._checkClosed()
    # Validate the final destination before making any changes
    if mode == os.SEEK_SET:
        if pos < 0:
            raise ValueError("seek of negative value with SEEK_SET")
    elif mode == os.SEEK_CUR:
        if pos < 0:
            new_pos = self._tell + pos
            if new_pos < 0:
                raise ValueError("seek of negative value with SEEK_CUR")
    elif mode == os.SEEK_END:
        pass  # negated already for end-based seeking
    else:
        raise ValueError(
            f"Invalid whence ({mode}, should be 0, 1, or 2)"
        )

    if mode == os.SEEK_SET:
        self.buffer.seek(0)
        self._traverse_codepoints(0, pos)
        self._tell = pos
    elif mode == os.SEEK_CUR:
        self._traverse_codepoints(self.tell(), pos)
        self._tell = self.tell()
    elif mode == os.SEEK_END:
        self.buffer.seek(0)
        dest_position = self.len - pos
        self._traverse_codepoints(0, dest_position)
        self._tell = dest_position
    return self.tell()
